import pytest

from shipquote import billable_kg, format_cents, quote_cents


def test_billable_kg_uses_volume():
    assert billable_kg(1, 50, 40, 30) == 12
    assert billable_kg(3.2, 10, 10, 10) == 4


def test_quote_local():
    assert quote_cents("local", 2, 10, 10, 10) == 646


def test_quote_remote():
    assert quote_cents("remote", 1, 10, 10, 10) == 1547


def test_unknown_zone():
    with pytest.raises(ValueError):
        quote_cents("moon", 1, 10, 10, 10)


def test_format_cents():
    assert format_cents(1234) == "EUR 12.34"
    assert format_cents(5) == "EUR 0.05"

