"""Price quotes for single parcels. Prices are in euro cents."""

from __future__ import annotations

import math

from shipquote.rates import FUEL_SURCHARGE_PERCENT, VOLUME_DIVISOR, ZONES


def billable_kg(weight_kg: float, length_cm: float, width_cm: float, height_cm: float) -> int:
    """Whole kg charged: the larger of real and volumetric weight, rounded up."""
    volumetric = length_cm * width_cm * height_cm / VOLUME_DIVISOR
    return math.ceil(max(weight_kg, volumetric))


def quote_cents(
    zone: str, weight_kg: float, length_cm: float, width_cm: float, height_cm: float
) -> int:
    """Price of one parcel to a zone, fuel surcharge included."""
    if zone not in ZONES:
        raise ValueError(f"unknown zone {zone!r}")
    base, per_kg = ZONES[zone]
    price = base + per_kg * billable_kg(weight_kg, length_cm, width_cm, height_cm)
    return price + price * FUEL_SURCHARGE_PERCENT // 100


def format_cents(cents: int) -> str:
    """Format cents for a receipt, for example 1234 -> "EUR 12.34"."""
    return f"EUR {cents // 100}.{cents % 100:02d}"


def receipt_line(zone: str, cents: int) -> str:
    """One receipt line, for example "national: EUR 8.74"."""
    return f"{zone}: {format_cents(cents)}"

